/* Scrubbed with the scroll: from the moment the wrapper's top enters the window, over 80% of
   the window's height of scroll, it fades from 0 to 1 and rises 16px into place. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .hermeus-reveal {
      animation: hermeus-reveal-rise linear both;
      animation-timeline: view();
      animation-range: entry 0px entry 80vh;
    }
  }
}

@keyframes hermeus-reveal-rise {
  from { opacity: 0; translate: 0 16px; }
  to { opacity: 1; translate: 0 0; }
}

import type { ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./hermeus-reveal.css";

export interface HermeusRevealProps {
  /** what fades and rises in */
  children: ReactNode;
  className?: string;
}

/** Fades and lifts its content in as it scrolls into view (scrubbed, CSS only). */
export function HermeusReveal({ children, className }: HermeusRevealProps) {
  return <div className={cn("hermeus-reveal", className)}>{children}</div>;
}
